//! The "about" model: a logistic regression over the pattern of a theme's words in a message
//! (see `tagger::ThemeHits::features`). A message mentions a theme when the theme's words
//! pass the rules in `tagger`; it is about the theme when the model's score reaches the
//! theme's threshold.
//!
//! Generated by tools/fit_model.py on 2026-10-28 from 914 hand-checked
//! (message, theme) pairs (522 judged about the theme). Do not edit by hand: re-run the
//! script after changing the lexicon or the features.
//!
//! Cross-validated on the checked pairs, the thresholds below keep 266 of them with
//! 95.1% precision and 48.5% recall. Fresh samples drawn from the about tier are the
//! real test (see the precision checks in the editors' pages).

/// Weights, in the order of `tagger::ThemeHits::features`.
pub static WEIGHTS: [f64; 31] = [
    0.623611, // title has a term
    0.768449, // ln(1+title weak words)
    0.379607, // ln(1+hits in the first two paragraphs)
    0.567216, // ln(1+hits per 1000 words)
    -0.414507, // share of paragraphs with hits
    1.003030, // ln(1+hits)
    0.014570, // ln(1+terms)
    -0.387376, // ln(1+words)
    0.506996, // ln(1+paragraphs with hits)
    -0.358742, // ln(1+hits in the busiest paragraph)
    -0.301756, // ln(1+themes mentioned)
    0.660754, // digest
    1.391061, // theme: east-timor
    -0.375511, // theme: aceh
    -0.733596, // theme: papua
    0.341551, // theme: communal-conflict
    -0.363351, // theme: labour
    -0.332909, // theme: students
    0.046942, // theme: press
    -0.135295, // theme: pdi-megawati
    -0.104158, // theme: left-1965
    -1.152910, // theme: islam
    1.282546, // theme: chinese
    -0.044155, // theme: military
    1.591228, // theme: human-rights
    -0.606476, // theme: economy
    0.803623, // theme: corruption
    -0.403166, // theme: elections
    -0.465413, // theme: environment
    -0.088018, // theme: women
    -0.692356, // theme: may-1998
];
pub const INTERCEPT: f64 = -0.105511;

/// Score at which a message counts as about each theme, chosen by cross-validation:
//   theme              threshold
//   east-timor         0.75  (41 of 49 checked messages above it, 100% correct)
//   aceh               0.75  (28 of 48 checked messages above it, 93% correct)
//   papua              0.90  (9 of 50 checked messages above it, 89% correct)
//   communal-conflict  0.75  (30 of 50 checked messages above it, 97% correct)
//   labour             0.90  (6 of 45 checked messages above it, 83% correct)
//   students           0.90  (4 of 35 checked messages above it, 100% correct)
//   press              0.75  (13 of 46 checked messages above it, 92% correct)
//   pdi-megawati       0.75  (13 of 48 checked messages above it, 100% correct)
//   left-1965          0.75  (14 of 50 checked messages above it, 93% correct)
//   islam              0.90  (4 of 48 checked messages above it, 75% correct)
//   chinese            0.75  (30 of 49 checked messages above it, 93% correct)
//   military           0.90  (6 of 50 checked messages above it, 100% correct)
//   human-rights       0.85  (set after the second precision check, from all checked messages)
//   economy            0.90  (3 of 49 checked messages above it, 100% correct)
//   corruption         0.85  (10 of 48 checked messages above it, 100% correct)
//   elections          0.90  (12 of 50 checked messages above it, 83% correct)
//   environment        0.75  (17 of 50 checked messages above it, 94% correct)
//   women              0.90  (set after the second precision check, from all checked messages)
//   may-1998           0.85  (set after the second precision check, from all checked messages)
pub static THRESHOLDS: &[(&str, f64)] = &[
    ("east-timor", 0.75),
    ("aceh", 0.75),
    ("papua", 0.90),
    ("communal-conflict", 0.75),
    ("labour", 0.90),
    ("students", 0.90),
    ("press", 0.75),
    ("pdi-megawati", 0.75),
    ("left-1965", 0.75),
    ("islam", 0.90),
    ("chinese", 0.75),
    ("military", 0.90),
    ("human-rights", 0.85),
    ("economy", 0.90),
    ("corruption", 0.85),
    ("elections", 0.90),
    ("environment", 0.75),
    ("women", 0.90),
    ("may-1998", 0.85),
];
pub const DEFAULT_THRESHOLD: f64 = 0.9;

pub fn threshold(slug: &str) -> f64 {
    THRESHOLDS.iter().find(|(s, _)| *s == slug).map(|t| t.1).unwrap_or(DEFAULT_THRESHOLD)
}

pub fn score(x: &[f64]) -> f64 {
    let z: f64 = INTERCEPT + x.iter().zip(WEIGHTS.iter()).map(|(a, b)| a * b).sum::<f64>();
    1.0 / (1.0 + (-z).exp())
}
